public class PiePlot_getMaximumExplodePercent_TriageGen0Test {

    private PiePlot piePlot;
    private PieDataset mockDataset;

    @Before
    public void setUp() {
        mockDataset = mock(PieDataset.class);
        piePlot = new PiePlot(mockDataset);
    }

    @Test
    public void testGetMaximumExplodePercent_EmptyDataset() {
        // Arrange: Dataset has no keys
        when(mockDataset.getKeys()).thenReturn(Collections.emptyList());

        // Act
        double result = piePlot.getMaximumExplodePercent();

        // Assert
        assertEquals(0.0, result, 0.001);
    }

    @Test
    public void testGetMaximumExplodePercent_AllNullExplode() {
        // Arrange: Dataset has keys, but no explode percentages are set
        when(mockDataset.getKeys()).thenReturn(Arrays.asList("A", "B"));
        // By default, setExplodePercent hasn't been called, so map returns null for these keys

        // Act
        double result = piePlot.getMaximumExplodePercent();

        // Assert
        assertEquals(0.0, result, 0.001);
    }

    @Test
    public void testGetMaximumExplodePercent_WithValues() {
        // Arrange: Setup keys and various explode percentages
        when(mockDataset.getKeys()).thenReturn(Arrays.asList("A", "B", "C"));

        piePlot.setExplodePercent("A", 0.1);
        piePlot.setExplodePercent("B", 0.5);
        piePlot.setExplodePercent("C", 0.3);

        // Act
        double result = piePlot.getMaximumExplodePercent();

        // Assert
        assertEquals(0.5, result, 0.001);
    }

    @Test
    public void testGetMaximumExplodePercent_MixedNullAndValues() {
        // Arrange: One key has a value, one is null
        when(mockDataset.getKeys()).thenReturn(Arrays.asList("A", "B"));

        piePlot.setExplodePercent("A", 0.2);
        // "B" is left as null in the internal map

        // Act
        double result = piePlot.getMaximumExplodePercent();

        // Assert
        assertEquals(0.2, result, 0.001);
    }

    @Test
    public void testGetMaximumExplodePercent_NegativeValues() {
        // Arrange: Even if values are negative (though unlikely in logic), 
        // the method initializes result to 0.0 and uses Math.max.
        when(mockDataset.getKeys()).thenReturn(Arrays.asList("A"));
        piePlot.setExplodePercent("A", -0.5);

        // Act
        double result = piePlot.getMaximumExplodePercent();

        // Assert
        assertEquals(0.0, result, 0.001);
    }

    @Test
    public void testGetMaximumExplodePercent_LargeValues() {
        // Arrange
        when(mockDataset.getKeys()).thenReturn(Arrays.asList("A", "B"));
        piePlot.setExplodePercent("A", 1.0);
        piePlot.setExplodePercent("B", 100.0);

        // Act
        double result = piePlot.getMaximumExplodePercent();

        // Assert
        assertEquals(100.0, result, 0.001);
    }
}
